import heapq

def match(orders):
    trades = []
    buy_heap = []   # heap of (-price, seq, id) for buy orders (max-heap by price)
    sell_heap = []  # heap of (price, seq, id) for sell orders (min-heap by price)
    book = {}       # id -> dict with side, price, qty, seq, active
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                entry = book[oid]
                if entry['active'] and entry['qty'] > 0:
                    entry['active'] = False
            continue

        oid = o[1]
        side = o[2]

        if typ == 'limit':
            price = o[3]
            qty = o[4]
        elif typ == 'ioc':
            price = o[3]
            qty = o[4]
        else:  # market
            qty = o[3]
            price = None

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                sell_order = book.get(top_id)
                if sell_order is None or (not sell_order['active']) or sell_order['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and top_price > price:
                    break
                trade_qty = min(remaining, sell_order['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                sell_order['qty'] -= trade_qty
                if sell_order['qty'] == 0:
                    sell_order['active'] = False
                    heapq.heappop(sell_heap)

            if typ == 'limit':
                if remaining > 0:
                    book[oid] = {'side': 'buy', 'price': price, 'qty': remaining,
                                 'seq': seq, 'active': True}
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    book[oid] = {'side': 'buy', 'price': price, 'qty': 0,
                                 'seq': seq, 'active': False}
            # ioc/market: remainder discarded, no book entry

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                buy_order = book.get(top_id)
                if buy_order is None or (not buy_order['active']) or buy_order['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and top_price < price:
                    break
                trade_qty = min(remaining, buy_order['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                buy_order['qty'] -= trade_qty
                if buy_order['qty'] == 0:
                    buy_order['active'] = False
                    heapq.heappop(buy_heap)

            if typ == 'limit':
                if remaining > 0:
                    book[oid] = {'side': 'sell', 'price': price, 'qty': remaining,
                                 'seq': seq, 'active': True}
                    heapq.heappush(sell_heap, (price, seq, oid))
                else:
                    book[oid] = {'side': 'sell', 'price': price, 'qty': 0,
                                 'seq': seq, 'active': False}
            # ioc/market: remainder discarded, no book entry

    return trades

